'use strict';
const $=id=>document.getElementById(id),players=new Map();let lastCatalog='',loading=false;
function message(text){$('status').textContent=text}
function stopAll(){for(const audio of players.values()){audio.pause();audio.currentTime=0}document.querySelectorAll('.play').forEach(button=>{button.textContent='▶ Play';button.classList.remove('playing');button.setAttribute('aria-pressed','false')})}
async function refresh(){if(loading)return;loading=true;try{const response=await fetch('./sounds.json',{cache:'no-store'});if(!response.ok)throw new Error();const sounds=await response.json();if(!Array.isArray(sounds))throw new Error();const serialized=JSON.stringify(sounds);if(serialized===lastCatalog)return;if([...players.values()].some(audio=>!audio.paused))return;lastCatalog=serialized;stopAll();players.clear();$('sounds').replaceChildren();$('count').textContent=sounds.length;$('empty').hidden=sounds.length>0;for(const sound of sounds){const card=document.createElement('article');card.className='card';const button=document.createElement('button');button.className='play';button.textContent='▶ Play';button.setAttribute('aria-label','Riproduci '+sound.label);button.setAttribute('aria-pressed','false');const label=document.createElement('div');label.className='label';label.textContent=sound.label;const audio=new Audio(sound.url);audio.preload='none';players.set(sound.url,audio);const reset=()=>{button.textContent='▶ Play';button.classList.remove('playing');button.setAttribute('aria-pressed','false')};audio.onended=reset;audio.onerror=()=>{reset();message('Audio non disponibile o formato non supportato. Prova un file MP3.')};button.onclick=async()=>{if(!audio.paused){audio.pause();reset();return}stopAll();try{await audio.play();button.textContent='Ⅱ Pausa';button.classList.add('playing');button.setAttribute('aria-pressed','true');message('')}catch{reset();message('Impossibile riprodurre questo suono. Controlla la connessione e il formato audio.')}};card.append(button,label);$('sounds').append(card)}message('')}catch{message('Raccolta non disponibile. Controlla la connessione e riprova.')}finally{loading=false}}
$('stop').onclick=stopAll;window.addEventListener('focus',refresh);setInterval(()=>{if(!document.hidden)refresh()},30000);refresh();
let installPrompt;window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;$('install').hidden=false});$('install').onclick=async()=>{if(!installPrompt)return;await installPrompt.prompt();installPrompt=null;$('install').hidden=true};
if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!sessionStorage.getItem('spirdo-sw-reloaded')){sessionStorage.setItem('spirdo-sw-reloaded','1');location.reload()}});navigator.serviceWorker.register('./sw.js').catch(()=>{})}
